import '../setup-filesystem-isolation.js';
import assert from 'node:assert/strict';
import {Database} from 'bun:sqlite';
import {join} from 'node:path';
import {renameSync} from 'node:fs';
import {initDatabase,getDb,closeDatabase} from '../../src/db/connection.js';
import {getStoreDir} from '../../src/core/config.js';
import {admitWebMessage} from '../../src/channels/web/messaging/message-store.js';
assert.equal(process.env.PICLAW_DB_IN_MEMORY,'0');
const phase=(name:string)=>console.log(JSON.stringify({fixturePhase:name}));
phase('init');initDatabase();phase('initialized');
const path=join(getStoreDir(),'messages.db');
const channel={broadcastEvent(){}};
const params={chatJid:'web:idle-disk',content:'disk input',isBot:false,mediaIds:[],agentId:'default',agentName:'Fixture'};
const rows=()=>(getDb().query('SELECT count(*) AS n FROM messages').get() as {n:number}).n;
const observe=(task:Promise<unknown>)=>task.then(value=>({ok:true as const,value}),error=>({ok:false as const,error}));
phase('cancel');let blocker=new Database(path);blocker.exec('BEGIN IMMEDIATE');
const abort=new AbortController();const cancelled=observe(admitWebMessage(channel,params,{},()=>{},abort.signal));await Bun.sleep(0);abort.abort(Error('cancelled'));const cancelledResult=await cancelled;assert.equal(cancelledResult.ok,false);assert.equal(rows(),0);blocker.exec('ROLLBACK');blocker.close();
phase('revoke');blocker=new Database(path);blocker.exec('BEGIN IMMEDIATE');let allowed=true;
const revoked=observe(admitWebMessage(channel,params,{},()=>{if(!allowed)throw Error('revoked');},new AbortController().signal));await Bun.sleep(0);allowed=false;blocker.exec('ROLLBACK');blocker.close();const revokedResult=await revoked;assert.equal(revokedResult.ok,false);assert.equal(rows(),0);
phase('reopen');blocker=new Database(path);blocker.exec('BEGIN IMMEDIATE');
const before=getDb();const reopened=observe(admitWebMessage(channel,params,{},()=>{},new AbortController().signal));await Bun.sleep(0);blocker.exec('ROLLBACK');blocker.close();await closeDatabase();initDatabase();assert.notEqual(getDb(),before);const reopenedResult=await reopened;assert.equal(reopenedResult.ok,false);assert.equal(rows(),0);
phase('replace');blocker=new Database(path);blocker.exec('BEGIN IMMEDIATE');
const replacement=observe(admitWebMessage(channel,params,{},()=>{},new AbortController().signal));await Bun.sleep(0);renameSync(path,path+'.old');const next=new Database(path);next.close();blocker.exec('ROLLBACK');blocker.close();const replacementResult=await replacement;assert.equal(replacementResult.ok,false);assert.equal(rows(),0);
await closeDatabase();console.log(JSON.stringify({kind:'idle-admission-disk',cancelled:true,revoked:true,reopenedRejected:true,replacedRejected:true,noRowsCommitted:true}));
